css:
.icecream-sim-container {
    padding: 24px;
    background: linear-gradient(180deg, #bde0fe 0%, #ffe5b4 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #2d3142;
}
.icecream-sim-header {
    background: linear-gradient(135deg, #ff6f61, #ffbe0b);
    color: #ffffff;
    border-radius: 24px;
    padding: 28px 32px;
    text-align: center;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(255, 111, 97, 0.28);
}
.icecream-sim-header h1 {
    font-size: 2rem;
    font-weight: 800;
    margin: 0;
    letter-spacing: -0.02em;
}
.icecream-sim-tagline {
    margin: 6px 0 0;
    font-size: 0.95rem;
    opacity: 0.92;
}
.icecream-sim-period-wrap {
    text-align: center;
    margin-bottom: 18px;
}
.icecream-sim-period-counter {
    display: inline-block;
    background: #ffffff;
    border-radius: 999px;
    padding: 8px 20px;
    font-weight: 700;
    color: #bd5046;
    box-shadow: 0 4px 14px rgba(0,0,0,0.08);
    letter-spacing: 0.02em;
}
.icecream-sim-briefing {
    background: #ffffff;
    border-radius: 22px;
    padding: 22px 26px;
    margin-bottom: 18px;
    border-left: 8px solid #ffbe0b;
    box-shadow: 0 8px 22px rgba(0,0,0,0.08);
}
.icecream-sim-briefing-row {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 18px;
    margin-bottom: 14px;
}
.icecream-sim-briefing-label {
    color: #8a8c94;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 4px;
}
.icecream-sim-briefing-value {
    color: #2d3142;
    font-size: 1.05rem;
    font-weight: 700;
    line-height: 1.3;
}
.icecream-sim-briefing-market {
    padding-top: 14px;
    border-top: 1px dashed #e8e8ed;
    display: flex;
    flex-wrap: wrap;
    gap: 28px;
    color: #4a4d57;
    font-size: 0.95rem;
}
.icecream-sim-briefing-market strong {
    color: #ff6f61;
    font-weight: 800;
}
.icecream-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 18px;
}
.icecream-sim-status-card {
    background: #ffffff;
    border-radius: 18px;
    padding: 18px 16px;
    text-align: center;
    box-shadow: 0 6px 18px rgba(0,0,0,0.07);
    position: relative;
    overflow: hidden;
    transition: transform 0.2s ease;
}
.icecream-sim-status-card:hover {
    transform: translateY(-3px);
}
.icecream-sim-status-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 4px;
    background: linear-gradient(90deg, #ff6f61, #ffbe0b);
}
.icecream-sim-label {
    color: #8a8c94;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 8px;
    font-weight: 600;
}
.icecream-sim-value {
    color: #2d3142;
    font-size: 1.6rem;
    font-weight: 800;
    line-height: 1;
}
.icecream-sim-controls {
    background: #ffffff;
    border-radius: 22px;
    padding: 24px 26px;
    margin-bottom: 18px;
    box-shadow: 0 8px 22px rgba(0,0,0,0.08);
}
.icecream-sim-controls h3 {
    font-size: 1.2rem;
    font-weight: 800;
    color: #ff6f61;
    margin: 0 0 6px;
}
.icecream-sim-prompt {
    color: #4a4d57;
    font-size: 0.95rem;
    margin-bottom: 18px;
}
.icecream-sim-control-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 18px;
    margin-bottom: 18px;
}
.icecream-sim-control label {
    display: block;
    color: #2d3142;
    font-weight: 700;
    margin-bottom: 6px;
    font-size: 0.95rem;
}
.icecream-sim-controls input[type="number"],
.icecream-sim-controls input[type="text"],
.icecream-sim-controls select {
    background: #fffaf2;
    border: 2px solid #ffe0a6;
    color: #2d3142;
    border-radius: 12px;
    padding: 11px 14px;
    width: 100%;
    font-size: 1rem;
    font-weight: 600;
    transition: border 0.2s ease, background 0.2s ease, box-shadow 0.2s ease;
}
.icecream-sim-controls input[type="number"]:focus,
.icecream-sim-controls input[type="text"]:focus,
.icecream-sim-controls select:focus {
    outline: none;
    border-color: #ff6f61;
    background: #ffffff;
    box-shadow: 0 0 0 4px rgba(255, 111, 97, 0.15);
}
.icecream-sim-controls select option {
    background: #ffffff;
    color: #2d3142;
}
.icecream-sim-action-row {
    display: flex;
    gap: 14px;
    align-items: center;
    flex-wrap: wrap;
}
.icecream-sim-submit {
    background: linear-gradient(135deg, #ff6f61, #ff8e53) !important;
    border: none !important;
    border-radius: 14px !important;
    padding: 13px 32px !important;
    font-weight: 800 !important;
    color: #ffffff !important;
    font-size: 1.02rem !important;
    box-shadow: 0 8px 18px rgba(255, 111, 97, 0.38);
    transition: transform 0.15s ease, box-shadow 0.15s ease;
    letter-spacing: 0.02em;
}
.icecream-sim-submit:hover {
    transform: translateY(-2px);
    box-shadow: 0 12px 24px rgba(255, 111, 97, 0.45);
}
.icecream-sim-results {
    background: #fffef5;
    border-radius: 22px;
    border: 2px dashed #ffbe0b;
    padding: 22px 26px;
    margin-bottom: 18px;
}
.icecream-sim-results h3 {
    font-size: 1.1rem;
    font-weight: 800;
    color: #ff6f61;
    margin: 0 0 12px;
}
.icecream-sim-results-text {
    color: #2d3142;
    font-size: 0.98rem;
    line-height: 1.6;
}
.icecream-sim-results-text .sold { color: #219652; font-weight: 800; }
.icecream-sim-results-text .melted { color: #d62828; font-weight: 800; }
.icecream-sim-results-text .shortage { color: #e67e22; font-weight: 800; }
.icecream-sim-results-text .stars-line {
    color: #ffbe0b;
    font-size: 1.3rem;
    letter-spacing: 3px;
    display: inline-block;
    margin-top: 4px;
}
.icecream-sim-history {
    background: #ffffff;
    border-radius: 22px;
    padding: 22px 26px;
    margin-bottom: 18px;
    box-shadow: 0 8px 22px rgba(0,0,0,0.08);
    overflow-x: auto;
}
.icecream-sim-history h3 {
    font-size: 1.1rem;
    font-weight: 800;
    color: #ff6f61;
    margin: 0 0 12px;
}
.icecream-sim-history table {
    margin-bottom: 0;
    width: 100%;
}
.icecream-sim-history table th {
    background: #fff3e0;
    color: #5a3a1a;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    border: none;
    padding: 10px 12px;
}
.icecream-sim-history table td {
    color: #2d3142;
    border-color: #f4f4f7;
    padding: 10px 12px;
    font-weight: 600;
}
.icecream-sim-charts {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 18px;
    margin-bottom: 18px;
}
.icecream-sim-chart-card {
    background: #ffffff;
    border-radius: 22px;
    padding: 18px;
    box-shadow: 0 8px 22px rgba(0,0,0,0.08);
    height: 300px;
}
.icecream-sim-chart-card canvas {
    max-height: 265px;
}
@media (max-width: 768px) {
    .icecream-sim-container { padding: 14px; }
    .icecream-sim-header { padding: 22px 20px; border-radius: 18px; }
    .icecream-sim-header h1 { font-size: 1.45rem; }
    .icecream-sim-briefing-row { grid-template-columns: 1fr; gap: 12px; }
    .icecream-sim-status-cards { grid-template-columns: repeat(2, 1fr); }
    .icecream-sim-control-row { grid-template-columns: 1fr; }
    .icecream-sim-charts { grid-template-columns: 1fr; }
    .icecream-sim-briefing-market { flex-direction: column; gap: 8px; }
    .icecream-sim-value { font-size: 1.3rem; }
    .icecream-sim-submit { width: 100%; }
}

/* ---- EQIL 2026-08-03 · accessibility + end-state + debrief (v1.1.0) ---- */
.icecream-sim-container :is(button, select, input, a):focus-visible,
:is(.icecream-sim-decisions, .icecream-sim-actions) :is(button, input):focus-visible {
    outline: 3px solid #1f5673;
    outline-offset: 2px;
    border-radius: 6px;
}
@media (prefers-reduced-motion: reduce) {
    .icecream-sim-container *, .icecream-sim-container *::before, .icecream-sim-container *::after {
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        scroll-behavior: auto !important;
    }
}
.icecream-sim-results-text .capnote { color: #7a5c17; font-size: 0.9em; }

.icecream-sim-complete {
    background: #fff6ee;
    border: 1px solid #f0d3b8;
    border-left: 5px solid #bd5046;
    border-radius: 10px;
    padding: 16px 20px;
    margin: 18px 0;
}
.icecream-sim-complete-title { margin: 0 0 6px; font-size: 17px; color: #6b2b23; font-weight: 700; }
.icecream-sim-complete-body  { margin: 0; font-size: 14px; color: #4a3a33; line-height: 1.55; }

.icecream-sim-debrief { margin: 18px 0; }
.icecream-sim-cm {
    background: #ffffff; border: 1px solid #f0d3b8; border-radius: 12px; padding: 20px 22px;
}
.icecream-sim-cm-title { margin: 0 0 12px; font-size: 18px; color: #6b2b23; font-weight: 700; }
.icecream-sim-cm-scorewrap { display: flex; align-items: baseline; gap: 8px; margin-bottom: 10px; }
.icecream-sim-cm-score { font-size: 42px; font-weight: 800; color: #bd5046; line-height: 1; }
.icecream-sim-cm-scoreof { font-size: 14px; color: #6d5c55; }
.icecream-sim-cm-grade {
    margin-left: 6px; padding: 2px 10px; border-radius: 999px;
    background: #bd5046; color: #ffffff; font-size: 14px; font-weight: 700;
}
.icecream-sim-cm-verdict { font-size: 15px; color: #3d2f2a; margin-bottom: 14px; }
.icecream-sim-cm-lbl { font-weight: 700; color: #6b2b23; }
.icecream-sim-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 8px; }
.icecream-sim-cm-kpi {
    display: flex; justify-content: space-between; gap: 10px;
    background: #fff8f2; border: 1px solid #f2ded0; border-radius: 8px; padding: 7px 10px;
}
.icecream-sim-cm-k { font-size: 12px; color: #6d5c55; }
.icecream-sim-cm-v { font-size: 13px; font-weight: 700; color: #3d2f2a; }
.icecream-sim-cm-sub { margin: 16px 0 8px; font-size: 14px; color: #6b2b23; font-weight: 700; }
.icecream-sim-cm-insights { margin: 0; padding-left: 20px; }
.icecream-sim-cm-insights li { font-size: 13.5px; color: #3d2f2a; line-height: 1.6; margin-bottom: 7px; }
@media (max-width: 640px) {
    .icecream-sim-cm { padding: 16px; }
    .icecream-sim-cm-score { font-size: 34px; }
    .icecream-sim-cm-kpis { grid-template-columns: 1fr 1fr; }
}

/* ---- EQIL 2026-10-27 · morning reading (prediction before the day, L3) + debrief sections ---- */
.icecream-sim-reading { margin-bottom: 18px; }
.icecream-sim-reading-help { margin: 6px 0 0; font-size: 0.85rem; color: #4a4d57; }
.icecream-sim-controls select { color-scheme: light; }
.icecream-sim-results-text .reading-ok { color: #1d6b3a; font-weight: 700; }
.icecream-sim-results-text .reading-no { color: #9b2c1f; font-weight: 700; }
.icecream-sim-cm-note { margin: 0 0 12px; font-size: 13px; color: #4a3a33; line-height: 1.5; }
.icecream-sim-cm-turn { margin: 0; font-size: 13.5px; color: #3d2f2a; line-height: 1.6; }
.icecream-sim-cm-mistakes li { border-left: 3px solid #bd5046; padding-left: 8px; list-style: none; margin-left: -20px; }
.icecream-sim-cm-questions { margin: 0; padding-left: 22px; }
.icecream-sim-cm-questions li { font-size: 13.5px; color: #3d2f2a; line-height: 1.6; margin-bottom: 6px; }
/* 360 px: the chart cards no longer push the page 5 px wide (F16) */
.icecream-sim-charts { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.icecream-sim-chart-card { min-width: 0; box-sizing: border-box; }
@media (max-width: 768px) { .icecream-sim-charts { grid-template-columns: minmax(0, 1fr); } }

