    'use strict';

    class IceCreamStallAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Maya Ice-Cream Stall';
            this.version = '1.2.0';
            this._finished = false;
            this.ROUNDS = [
                { num: 1, titleKey: 'round1_title', weatherKey: 'round1_weather', newsKey: 'round1_news', demandA: 580, demandB: 200, cost: 0.70, capacity: 300, starP: 1.80, starQ: 220, moved: 'none' },
                { num: 2, titleKey: 'round2_title', weatherKey: 'round2_weather', newsKey: 'round2_news', demandA: 780, demandB: 200, cost: 0.70, capacity: 300, starP: 2.30, starQ: 320, moved: 'dright' },
                { num: 3, titleKey: 'round3_title', weatherKey: 'round3_weather', newsKey: 'round3_news', demandA: 580, demandB: 200, cost: 1.20, capacity: 300, starP: 2.05, starQ: 170, moved: 'costup' },
                { num: 4, titleKey: 'round4_title', weatherKey: 'round4_weather', newsKey: 'round4_news', demandA: 380, demandB: 200, cost: 0.70, capacity: 300, starP: 1.30, starQ: 120, moved: 'dleft' },
                { num: 5, titleKey: 'round5_title', weatherKey: 'round5_weather', newsKey: 'round5_news', demandA: 680, demandB: 200, cost: 0.70, capacity: 150, starP: 2.65, starQ: 150, moved: 'dright_cap' }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 0,
                    totalProfit: 0,
                    totalStars: 0,
                    profitHistory: [],
                    salesHistory: [],
                    priceHistory: [],
                    starsHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // no default price or stock: the old defaults matched the day 1 equilibrium, so the inputs start blank
                state.decisions = { price: null, stock: null };
            }
            this._finished = (state.currentPeriod || 1) > this.ROUNDS.length;
            var self = this;
            setTimeout(function() {
                self._updateBriefing(state);
                self._syncControlsFromDecisions(state);
            }, 50);
        }

        // On resume the framework restores state.decisions but the DOM still shows the
        // authored defaults. validateDecisions reads the DOM, so without this the player
        // silently loses their saved choices the moment they submit.
        _syncControlsFromDecisions(state) {
            var d = (state && state.decisions) || {};
            var p = document.getElementById('priceInput');
            var s = document.getElementById('stockInput');
            if (p && typeof d.price === 'number' && isFinite(d.price)) p.value = String(d.price);
            if (s && typeof d.stock === 'number' && isFinite(d.stock)) s.value = String(d.stock);
        }

        // Grading contract C1-C4. The sim shipped no 0-100 composite at all, so one is
        // introduced here; it is the star ratio, which reproduces the bands the sim
        // already used (90 / 70 / 50 percent) so score and verdict agree by construction.
        _composite(stars, periods) {
            var max = Math.max(1, periods * 3);
            return Math.round(Math.max(0, Math.min(100, (stars / max) * 100)));
        }
        _tier(score) {
            if (score >= 90) return 'market_maker';
            if (score >= 70) return 'sharp_reader';
            if (score >= 50) return 'apprentice';
            return 'beginner';
        }
        _grade(score) {
            if (score >= 90) return 'A';
            if (score >= 70) return 'B';
            if (score >= 50) return 'C';
            return 'D';
        }
        _t(key, vars) {
            var s = key;
            if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                try { s = window.mySimulation.t(key); } catch (e) { s = key; }
            }
            if (s === undefined || s === null) s = key;
            if (vars) Object.keys(vars).forEach(function(k) { s = String(s).split('{' + k + '}').join(vars[k]); });
            return s;
        }

        validateDecisions(decisions) {
            var state = (window.mySimulation && window.mySimulation.state) ? window.mySimulation.state : { currentPeriod: 1 };
            var round = this._currentRound(state);
            var priceInput = document.getElementById('priceInput');
            var stockInput = document.getElementById('stockInput');
            if ((priceInput && String(priceInput.value).trim() === '') || (stockInput && String(stockInput.value).trim() === '')) {
                window.mySimulation.uiManager.showNotification(this._t('blank_warning'), 'warning');
                return false;
            }
            var readingInput = document.getElementById('readingInput');
            if (readingInput) {
                var rv = String(readingInput.value || '');
                if (['none', 'dright', 'dleft', 'costup', 'dright_cap'].indexOf(rv) < 0) {
                    window.mySimulation.uiManager.showNotification(this._t('reading_warning'), 'warning');
                    return false;
                }
                decisions.reading = rv;
            }
            if (priceInput) {
                var rawPrice = parseFloat(priceInput.value);
                // The control steps in 5p; a typed 1.834 otherwise scores and prices off a
                // figure the student is never shown, because every display uses toFixed(2).
                if (isFinite(rawPrice)) {
                    rawPrice = Math.round(rawPrice * 20) / 20;
                    priceInput.value = rawPrice.toFixed(2);
                }
                decisions.price = rawPrice;
            }
            if (stockInput) {
                var rawStock = parseInt(stockInput.value, 10);
                if (isFinite(rawStock)) stockInput.value = String(rawStock);
                decisions.stock = rawStock;
            }

            if (isNaN(decisions.price) || decisions.price < 1.00 || decisions.price > 4.00) {
                window.mySimulation.uiManager.showNotification(
                    this._t('price_warning'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.stock) || decisions.stock < 0 || decisions.stock > 300) {
                window.mySimulation.uiManager.showNotification(
                    this._t('stock_warning'), 'warning'
                );
                return false;
            }
            if (decisions.stock > round.capacity) {
                window.mySimulation.uiManager.showNotification(
                    this._t('capacity_warning') + ' ' + round.capacity, 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var round = this._currentRound(state);
            var d = state.decisions;
            var price = d.price;
            var stock = d.stock;

            var demandAtPrice = Math.max(0, Math.round(round.demandA - round.demandB * price));
            var sales = Math.min(stock, demandAtPrice);
            var revenue = sales * price;
            var totalCost = stock * round.cost;
            var profit = revenue - totalCost;
            var melted = stock - sales;
            var shortage = Math.max(0, demandAtPrice - stock);

            var priceDistance = Math.abs(price - round.starP) / round.starP;
            var stockDistance = round.starQ > 0 ? Math.abs(stock - round.starQ) / round.starQ : 0;
            var stars = 0;
            if (priceDistance <= 0.05 && stockDistance <= 0.10) {
                stars = 3;
            } else if (priceDistance <= 0.15 && stockDistance <= 0.25) {
                stars = 2;
            } else if (stock > 0 && melted <= stock * 0.50 && (demandAtPrice === 0 || shortage <= demandAtPrice * 0.50)) {
                stars = 1;
            }

            state.domainState.cash += profit;
            state.domainState.totalProfit += profit;
            state.domainState.totalStars += stars;
            state.domainState.profitHistory.push(Math.round(profit * 100) / 100);
            state.domainState.salesHistory.push(sales);
            state.domainState.priceHistory.push(price);
            state.domainState.starsHistory.push(stars);
            var reading = (typeof d.reading === 'string') ? d.reading : null;
            var readingRight = reading === round.moved;
            if (!state.domainState.readingsHistory) state.domainState.readingsHistory = [];
            state.domainState.readingsHistory.push(reading === null ? null : (readingRight ? 1 : 0));

            var periodsPlayed = state.domainState.starsHistory.length;
            var overall = this._composite(state.domainState.totalStars, periodsPlayed);
            state.domainState.performance = { overallScore: overall, grade: this._grade(overall) };
            state.domainState.performanceTier = this._tier(overall);

            this._updateResultsPanel({
                price: price, stock: stock, sales: sales, demandAtPrice: demandAtPrice,
                revenue: revenue, totalCost: totalCost, profit: profit,
                melted: melted, shortage: shortage, stars: stars,
                equilibriumPrice: round.starP, equilibriumQuantity: round.starQ,
                capacity: round.capacity, reading: reading, readingRight: readingRight, moved: round.moved
            });

            this._finished = state.currentPeriod >= this.ROUNDS.length;
            var self = this;
            var nextPeriod = state.currentPeriod + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod });
            }, 500);

            return {
                period: state.currentPeriod,
                overallScore: overall,
                score: overall,
                totalScore: overall,
                price: price,
                stock: stock,
                sales: sales,
                demandAtPrice: demandAtPrice,
                revenue: revenue,
                totalCost: totalCost,
                profit: profit,
                melted: melted,
                shortage: shortage,
                stars: stars,
                equilibriumPrice: round.starP,
                equilibriumQuantity: round.starQ,
                reading: reading,
                readingRight: readingRight,
                moved: round.moved
            };
        }

        setupUI(uiManager) {
            var self = this;
            var money = function(v) { return self._money(v); };
            if (!this._langBound) {
                this._langBound = true;
                var repaint = function() {
                    try {
                        var st = window.mySimulation && window.mySimulation.state;
                        if (st) self._updateBriefing(st);
                        if (st) self._chartAlt(st.domainState);
                        if (self._lastPanel) self._updateResultsPanel(self._lastPanel);
                        var host = document.getElementById('icecreamDebrief');
                        if (host && host.style.display === 'block' && st && st.history && st.history.length) {
                            self.formatCompletionMessage(self.getPerformanceSummary(st.history));
                        }
                        if (st && window.mySimulation.uiManager && typeof window.mySimulation.uiManager.updateFromState === 'function') {
                            window.mySimulation.uiManager.updateFromState(st);
                        }
                    } catch (e) {}
                };
