                try { if (window.mySimulation && window.mySimulation.eventBus) window.mySimulation.eventBus.on('language:changed', function() { setTimeout(repaint, 0); }); } catch (e) {}
            }
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash', money);
            uiManager.bind('weekProfitDisplay', 'domainState.totalProfit', money);
            uiManager.bind('starsDisplay', 'domainState.totalStars',
                function(v) { return v + ' ⭐'; });
            uiManager.bind('lastProfitDisplay', 'results.profit', money);
        }

        getChartConfig() {
            var t = this._t.bind(this);
            return {
                profitChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: t('chart_profit_title'),
                            data: [],
                            backgroundColor: 'rgba(255, 111, 97, 0.75)',
                            borderColor: '#ff6f61',
                            borderWidth: 2,
                            borderRadius: 8
                        }]
                    },
