                    }
                },
                demandChart: {
                    type: 'scatter',
                    data: {
                        labels: [],
                        datasets: [{
                            label: t('chart_demand_title'),
                            data: [],
                            backgroundColor: '#ffbe0b',
                            borderColor: '#ff6f61',
                            pointRadius: 9,
