                        plugins: {
                            title: { display: true, text: t('chart_demand_title') },
                            legend: { display: false }
                        },
                        scales: {
                            x: { title: { display: true, text: t('chart_axis_units') }, beginAtZero: true },
                            y: { title: { display: true, text: t('chart_axis_price') }, beginAtZero: true }
                        }
                    }
                }
            };
        }

        // Tolerates a partially restored session: domainState or its history arrays can be absent.
        // Text alternative for both canvases (F21), written in the run language.
        _chartAlt(ds) {
            var self = this, dayLbl = this._t('day_label');
            var ph = (ds && ds.profitHistory) || [], pr = (ds && ds.priceHistory) || [], sh = (ds && ds.salesHistory) || [];
            var a = document.getElementById('profitChart'), b = document.getElementById('demandChart');
            var list1 = ph.map(function(v, i) { return dayLbl + ' ' + (i + 1) + ': ' + self._money(v); }).join('; ');
            var list2 = pr.map(function(v, i) { return dayLbl + ' ' + (i + 1) + ': ' + self._money(v) + ', ' + (sh[i] || 0) + ' ' + self._t('cones_suffix'); }).join('; ');
            if (a) a.setAttribute('aria-label', this._t('chart_profit_title') + '. ' + (list1 || this._t('chart_alt_empty')));
            if (b) b.setAttribute('aria-label', this._t('chart_demand_title') + '. ' + (list2 || this._t('chart_alt_empty')));
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var profitHistory = ds.profitHistory || [];
            var priceHistory = ds.priceHistory || [];
            var salesHistory = ds.salesHistory || [];
            try { this._chartAlt(ds); } catch (e) {}
            var dayLbl = this._t('day_label');
            var labels = profitHistory.map(function(_, i) { return dayLbl + ' ' + (i + 1); });
            var scatterData = priceHistory.map(function(p, i) {
                return { x: salesHistory[i] || 0, y: p };
            });
            return {
                profitChart: {
                    labels: labels,
                    datasets: [{ data: profitHistory }]
                },
                demandChart: {
                    datasets: [{ data: scatterData }]
                }
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.stars === 3) return this._t('hint_perfect');
            if (results.melted > Math.max(10, results.stock * 0.3)) return this._t('hint_surplus');
            if (results.shortage > 20) return this._t('hint_shortage');
            if (results.profit < 0) return this._t('hint_loss');
            if (results.price > results.equilibriumPrice * 1.15) return this._t('hint_price_high');
            if (results.price < results.equilibriumPrice * 0.85) return this._t('hint_price_low');
            return null;
        }

        getHistoryTableConfig() {
            var self = this;
            return [
                { key: 'results.price',  label: 'Price',    i18nKey: 'col_price',  formatter: function(v) { return self._money(v); } },
                { key: 'results.stock',  label: 'Produced', i18nKey: 'col_stock' },
                { key: 'results.sales',  label: 'Sold',     i18nKey: 'col_sales' },
                { key: 'results.melted', label: 'Melted',   i18nKey: 'col_melted' },
                { key: 'results.profit', label: 'Profit',   i18nKey: 'col_profit', formatter: function(v) { return self._money(v); } },
                { key: 'results.stars',  label: 'Stars',    i18nKey: 'col_stars',  formatter: function(v) { return v > 0 ? '⭐'.repeat(v) : '—'; } }
            ];
        }

        // Language of the run: vcI18n is the live source (Lessons_Learned 2026-08-20).
        _lang() {
            try { if (window.vcI18n && window.vcI18n._lang) return window.vcI18n._lang; } catch (e) {}
            var h = document.documentElement && document.documentElement.lang;
            return h ? String(h).slice(0, 2) : 'en';
        }
        // Pounds in the run language: decimal comma in Spanish.
        _money(v) {
            var n = Math.round((Number(v) || 0) * 100) / 100;
            var parts = Math.abs(n).toFixed(2).split('.');
            var es = this._lang() === 'es';
            var whole = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, es ? '.' : ',');
            var txt = whole + (es ? ',' : '.') + parts[1];
            return (n < 0 ? '−£' : '£') + txt;
        }
        // The most profitable price on a daily board (5p steps) with the batch matched to the
        // cones wanted at that price, capped by the freezer. Same demand and cost as calculateResults.
        _bestDay(round) {
            var best = { price: 1, stock: 0, profit: -Infinity };
            for (var c = 100; c <= 400; c += 5) {
                var p = c / 100;
                var q = Math.min(round.capacity, Math.max(0, Math.round(round.demandA - round.demandB * p)));
                var pr = q * (p - round.cost);
                if (pr > best.profit + 1e-9) best = { price: p, stock: q, profit: pr };
            }
            best.profit = Math.round(best.profit * 100) / 100;
            return best;
        }
        // One row per traded day, read from the run own history (never from what the player might have done).
        _days(history) {
            var self = this;
            return (history || []).map(function(h, i) {
                var r = (h && h.results) || {};
                var period = (typeof r.period === 'number') ? r.period : ((h && h.period) || (i + 1));
                var round = self.ROUNDS[Math.min(Math.max(period - 1, 0), self.ROUNDS.length - 1)];
                return { n: period, round: round, best: self._bestDay(round), r: r };
            }).filter(function(d) { return typeof d.r.price === 'number' && typeof d.r.stock === 'number'; });
        }
        // The mistakes the teaching note names (TN 13, Q1-Q5), detected from the run history.
        _mistakes(days) {
            var self = this, out = [];
            var base = this.ROUNDS[0];
            var mon = days.filter(function(d) { return d.n === 1; })[0];
            var dname = function(d) { return self._t('day_label') + ' ' + d.n + ' (' + self._t(d.round.titleKey) + ')'; };
            var near = function(a, b) { return Math.abs(a.price - b.price) <= 0.051 && Math.abs(a.stock - b.stock) <= Math.max(5, 0.10 * Math.max(a.stock, b.stock)); };
            // Mondaily numbers carried into a day whose news moved the beach (TN 13, Q1)
            if (mon) days.forEach(function(d) {
                if (d.n > 1 && d.round.demandA !== base.demandA && d.r.stars < 3 && near(d.r, mon.r)) {
                    out.push({ id: 'monday', text: self._t('mk_monday', { day: dname(d), p: self._money(mon.r.price), q: mon.r.stock, melt: d.r.melted, short: d.r.shortage, profit: self._money(d.r.profit), bp: self._money(d.best.price), bq: d.best.stock }) });
                }
            });
            // Cost rise: how much of it reached the price (TN 5.2, Q2, Exhibit 4)
            days.forEach(function(d) {
                if (d.round.cost <= base.cost) return;
                var rise = d.round.cost - base.cost;
                var before = (base.cost + d.round.demandA / d.round.demandB) / 2;
                var passed = d.r.price - before;
                if (passed >= 0.9 * rise - 1e-9) {
                    out.push({ id: 'passall', text: self._t('mk_passall', { day: dname(d), p: self._money(d.r.price), rise: self._money(rise), half: self._money(rise / 2), bp: self._money(d.best.price), profit: self._money(d.r.profit), bprofit: self._money(d.best.profit) }) });
                } else if (passed <= 0.05 + 1e-9) {
                    out.push({ id: 'passnone', text: self._t('mk_passnone', { day: dname(d), p: self._money(d.r.price), rise: self._money(rise), bp: self._money(d.best.price), profit: self._money(d.r.profit), bprofit: self._money(d.best.profit) }) });
                }
            });
            // A capped freezer rationed by the queue instead of the price (TN 5.5, Q4, Exhibit 5)
            days.forEach(function(d) {
                if (d.round.capacity >= 300) return;
                if (d.r.stock >= 0.9 * d.round.capacity && d.r.shortage > 0.15 * Math.max(1, d.r.demandAtPrice)) {
                    out.push({ id: 'queue', text: self._t('mk_queue', { day: dname(d), short: d.r.shortage, p: self._money(d.r.price), cap: d.round.capacity, bp: self._money(d.best.price), profit: self._money(d.r.profit), bprofit: self._money(d.best.profit) }) });
                }
            });
            // Sold out, so it looked right: a cleared stall at a price below the daily best (TN 13, Q3, Exhibit 3)
            var cleared = days.filter(function(d) { return d.r.stock > 0 && d.r.melted === 0 && d.r.shortage === 0 && d.r.price < d.best.price - 0.051; });
            if (cleared.length) {
                var c0 = cleared[0];
                out.push({ id: 'cleared', text: self._t('mk_cleared', { n: cleared.length, day: dname(c0), q: c0.r.stock, p: self._money(c0.r.price), bp: self._money(c0.best.price), gap: self._money(c0.best.profit - c0.r.profit) }) });
            }
            // Short below capacity on two days or more: the melt-averse batch (TN Q5 Never waste, 5.4)
            var shortDays = days.filter(function(d) { return d.r.shortage > 0 && d.r.stock < d.round.capacity; });
            if (shortDays.length >= 2) {
                var lost = shortDays.reduce(function(a, d) { return a + d.r.shortage; }, 0);
                out.push({ id: 'meltaverse', text: self._t('mk_meltaverse', { n: shortDays.length, lost: lost, days: shortDays.map(function(d) { return d.n; }).join(', ') }) });
            }
            // Yesterdaily numbers copied into a new day (the boxes keep them; TN 12.1, 13)
            days.forEach(function(d) {
                if (d.n < 2 || d.r.stars === 3) return;
                var prev = days.filter(function(x) { return x.n === d.n - 1; })[0];
                if (!prev || near(d.r, prev.r) === false) return;
                if (out.some(function(m) { return m.id === 'monday' && m.text.indexOf(dname(d)) >= 0; })) return;
                out.push({ id: 'copied', text: self._t('mk_copied', { day: dname(d), p: self._money(d.r.price), q: d.r.stock, profit: self._money(d.r.profit) }) });
            });
            return out;
        }
        // The day that cost the most against the best play that day (S4 turning point).
        _turningPoint(days) {
            var worst = null;
            days.forEach(function(d) {
                var gap = d.best.profit - d.r.profit;
                if (!worst || gap > worst.gap + 1e-9) worst = { d: d, gap: gap };
            });
            if (!worst || worst.gap < 5) return this._t('tp_none');
            var d = worst.d, r = d.r, cause;
            if (r.melted > 0 && r.melted >= r.shortage) cause = this._t('tp_cause_melt', { melt: r.melted, p: this._money(r.price), want: r.demandAtPrice });
            else if (r.shortage > 0) cause = this._t('tp_cause_short', { short: r.shortage, p: this._money(r.price) });
            else cause = this._t('tp_cause_price', { p: this._money(r.price), bp: this._money(d.best.price) });
            return this._t('tp_line', { day: this._t('day_label') + ' ' + d.n + ' (' + this._t(d.round.titleKey) + ')', profit: this._money(r.profit), bprofit: this._money(d.best.profit), bp: this._money(d.best.price), bq: d.best.stock }) + ' ' + cause;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalProfit = history.reduce(function(s, r) { return s + ((r.results && r.results.profit) || 0); }, 0);
            var totalStars  = history.reduce(function(s, r) { return s + ((r.results && r.results.stars)  || 0); }, 0);
            var maxStars = history.length * 3;

            var score = this._composite(totalStars, history.length);
            var tier = this._tier(score);

            var days = this._days(history);
            var bestWeek = days.reduce(function(a, d) { return a + d.best.profit; }, 0);
            var share = bestWeek > 0 ? Math.round(100 * totalProfit / bestWeek) : 0;
            var mistakes = this._mistakes(days);
            var read = days.filter(function(d) { return typeof d.r.reading === 'string'; });
            var readRight = read.filter(function(d) { return d.r.readingRight === true; });
            var misread = read.filter(function(d) { return d.r.readingRight !== true; });
            var turning = this._turningPoint(days);

            var insights = [];
            insights.push(this._t('insight_profit_share', { profit: this._money(totalProfit), best: this._money(bestWeek), share: share }));
            if (totalStars === maxStars) insights.push(this._t('insight_perfect_week'));
            if (totalProfit < 0) insights.push(this._t('insight_loss_week'));
            var lossDays = days.filter(function(d) { return d.r.profit < 0; }).map(function(d) { return d.n; });
            if (lossDays.length && totalProfit >= 0) insights.push(this._t('insight_loss_days', { days: lossDays.join(', ') }));
            if (!mistakes.length) insights.push(this._t('insight_no_traps'));
            if (read.length) {
                var self2 = this;
                insights.push(misread.length ? this._t('insight_misread', { days: misread.map(function(d) { return d.n + ' (' + self2._t('reading_' + d.round.moved) + ')'; }).join('; ') }) : this._t('insight_read_all'));
            }
            insights.push(this._t('insight_debrief'));

            return {
                score: score,
                overallScore: score,
                totalScore: score,
                composite: score,
                grade: this._grade(score),
                performance: tier,
                performanceKey: 'band_' + tier,
                performanceLabel: this._t('band_' + tier),
                periods: history.length,
                totalProfit: Math.round(totalProfit * 100) / 100,
                bestProfit: Math.round(bestWeek * 100) / 100,
                profitShare: share,
                totalStars: totalStars,
                maxStars: maxStars,
                outcomeScore: score,
                readingsRight: readRight.length,
                readingsTotal: read.length,
                turningPoint: turning,
                mistakes: mistakes.map(function(m) { return m.text; }),
                mistakeIds: mistakes.map(function(m) { return m.id; }),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var t = this._t.bind(this);
            var self = this;
            var stars = s.totalStars || 0, max = s.maxStars || 0;
            var rows = [
                [t('cm_stars'), stars + ' / ' + max],
                [t('cm_profit'), this._money(s.totalProfit || 0)],
                [t('cm_best_profit'), this._money(s.bestProfit || 0) + (typeof s.profitShare === 'number' ? ' (' + s.profitShare + '%)' : '')],
                [t('cm_days'), String(s.periods || 0)]
            ];
            if (s.readingsTotal) rows.splice(1, 0, [t('cm_readings'), s.readingsRight + ' / ' + s.readingsTotal]);
            var li = function(arr) { return (arr || []).map(function(i) { return '<li>' + i + '</li>'; }).join(''); };
            var mistakes = s.mistakes || [];
            var html = '<div class="icecream-sim-cm">' +
                '<h3 class="icecream-sim-cm-title">' + t('cm_title') + '</h3>' +
                '<div class="icecream-sim-cm-scorewrap">' +
                    '<span class="icecream-sim-cm-score">' + Math.round(s.score || 0) + '</span>' +
                    '<span class="icecream-sim-cm-scoreof">' + t('cm_score_of') + '</span>' +
                    '<span class="icecream-sim-cm-grade">' + (s.grade || '') + '</span>' +
                '</div>' +
                '<div class="icecream-sim-cm-verdict"><span class="icecream-sim-cm-lbl">' + t('cm_verdict') + ':</span> ' +
                    (s.performanceLabel || t('band_' + (s.performance || 'beginner'))) + '</div>' +
                '<p class="icecream-sim-cm-note">' + t('cm_score_rule') + '</p>' +
                '<div class="icecream-sim-cm-kpis">' + rows.map(function(r) {
                    return '<div class="icecream-sim-cm-kpi"><span class="icecream-sim-cm-k">' + r[0] +
                           '</span><span class="icecream-sim-cm-v">' + r[1] + '</span></div>';
                }).join('') + '</div>' +
                (s.turningPoint ? '<h4 class="icecream-sim-cm-sub">' + t('cm_turning') + '</h4><p class="icecream-sim-cm-turn">' + s.turningPoint + '</p>' : '') +
                (mistakes.length ? '<h4 class="icecream-sim-cm-sub">' + t('cm_mistakes') + '</h4><ul class="icecream-sim-cm-insights icecream-sim-cm-mistakes">' + li(mistakes) + '</ul>' : '') +
                '<h4 class="icecream-sim-cm-sub">' + t('cm_insights') + '</h4>' +
                '<ul class="icecream-sim-cm-insights">' + li(s.insights) + '</ul>' +
                '<h4 class="icecream-sim-cm-sub">' + t('cm_questions') + '</h4>' +
                '<ol class="icecream-sim-cm-questions">' + li([t('dq_1'), t('dq_2'), t('dq_3')]) + '</ol>' +
                '</div>';
            // Rendered in page too: the debrief must not depend on a modal firing.
            var host = document.getElementById('icecreamDebrief');
            if (host) { host.innerHTML = html; host.style.display = 'block'; host.setAttribute('aria-label', t('cm_title')); }
            return html;
        }

        getPresets() { return null; }

        _currentRound(state) {
            var idx = Math.min(Math.max((state.currentPeriod || 1) - 1, 0), this.ROUNDS.length - 1);
            return this.ROUNDS[idx];
        }

        _updateBriefing(state) {
            var period = (state && state.currentPeriod) || 1;
            var done = period > this.ROUNDS.length;
            var idx = Math.min(Math.max(period - 1, 0), this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var t = this._t.bind(this);

            // No dead end: once the week is over the decision surface goes away.
            var controls = document.getElementById('icecreamControls');
            if (controls) controls.style.display = done ? 'none' : 'block';
            var brief = document.getElementById('briefingCard');
            if (brief) brief.style.display = done ? 'none' : 'block';
            var notice = document.getElementById('icecreamCompleteNotice');
            if (notice) notice.style.display = done ? 'block' : 'none';
            if (done) {
                var btn = document.getElementById('nextPeriodBtn');
                if (btn) btn.disabled = true;
                return;
            }

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl) titleEl.textContent = t(round.titleKey);
            var weatherEl = document.getElementById('briefingWeather');
            if (weatherEl) weatherEl.textContent = t(round.weatherKey);
            var newsEl = document.getElementById('briefingNews');
            if (newsEl) newsEl.textContent = t(round.newsKey);

            var costEl = document.getElementById('marketCost');
            if (costEl) costEl.textContent = this._money(round.cost);
            var capEl = document.getElementById('marketCapacity');
            if (capEl) capEl.textContent = round.capacity + ' ' + t('cones_suffix');

            var stockInput = document.getElementById('stockInput');
            if (stockInput) {
                // the cap is not written into the input: on day 5 it equals the scored quantity; validateDecisions refuses stock above it
                stockInput.max = round.capacity;
            }
        }

        _updateResultsPanel(r) {
            var panel = document.getElementById('resultsText');
            if (!panel) return;
            var t = this._t.bind(this);
            var m = this._money.bind(this);
            this._lastPanel = r;
            var starStr = r.stars > 0 ? '⭐'.repeat(r.stars) : '—';
            var soldHtml = '<span class="sold">' + r.sales + '</span>';
            var meltedHtml = '<span class="melted">' + r.melted + '</span>';
            var lines = [];
            lines.push('<strong>' + t('result_price') + ':</strong> ' + m(r.price) + ' · <strong>' + t('result_produced') + ':</strong> ' + r.stock + ' · <strong>' + t('result_demand') + ':</strong> ' + r.demandAtPrice);
            var line2 = '<strong>' + t('result_sold') + ':</strong> ' + soldHtml + ' · <strong>' + t('result_melted') + ':</strong> ' + meltedHtml;
            if (r.shortage > 0) {
                line2 += ' · <span class="shortage">' + t('result_shortage') + ': ' + r.shortage + '</span>';
            }
            lines.push(line2);
            lines.push('<strong>' + t('result_revenue') + ':</strong> ' + m(r.revenue) + ' · <strong>' + t('result_cost') + ':</strong> ' + m(r.totalCost) + ' · <strong>' + t('result_profit') + ':</strong> ' + m(r.profit));
            var eqLine = '<em>' + t('result_equilibrium') + ':</em> ' + m(r.equilibriumPrice) + ' @ ' + r.equilibriumQuantity + ' ' + t('cones_suffix');
            if (r.capacity && r.equilibriumQuantity > r.capacity) {
                eqLine += ' <span class="capnote">' + t('result_capacity_note', { cap: r.capacity }) + '</span>';
            }
            lines.push(eqLine);
            if (r.moved) {
                var mv = '<strong>' + t('result_moved') + ':</strong> ' + t('reading_' + r.moved);
                if (r.reading) {
                    mv += ' · <strong>' + t('result_reading') + ':</strong> ' + t('reading_' + r.reading) + ' ' +
                        (r.readingRight ? '<span class="reading-ok">✓ ' + t('reading_right') + '</span>' : '<span class="reading-no">✗ ' + t('reading_wrong') + '</span>');
                }
                lines.push(mv);
            }
            lines.push('<span class="stars-line">' + starStr + '</span>');
            panel.innerHTML = lines.join('<br>');
        }

